preConditionHook:
// THE MAJOR TREND REVERSAL, one of the named Brooks setups the merge pass keeps
// WHOLE so Brian can test it as the book states it: a strong trend line break,
// then a FAILED TEST of the trend's extreme, then a strong reversal signal bar
// on that test. Its parts live in other rules (TrendLineBreak,
// ExtremeTestAfterTrendLineBreak, a signal-bar test) and are INLINED here, as
// the corpus does with every named composite -- rules never reference each
// other -- but the sequence is not reachable by ANDing panes, because the level
// being tested is THE TREND EXTREME AS IT STOOD AT THE BREAK and no separate
// pane can hand that across.
//
// V03-06's fourth item, "the second reversal goes far enough for a consensus
// that the trend has reversed", is DROPPED rather than parameterized: Brooks
// gives no number, and inventing a consensus threshold would put the whole
// setup out of reach for no gain. With it gone every part is measurable.
//
// THE TREND LINE AND ITS PIVOTS, the one construction shared by the whole
// lines/channels family (settled in slice B01, recorded in author/DECISIONS.md,
// carried here unchanged): the BULL trend line runs through the two most recent
// CONFIRMED swing LOWS and the BEAR line through the two most recent confirmed
// swing HIGHS; the two are deliberately not parallel.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR BEYOND the strength OLDER bars, STRICTLY BEYOND the
// strength NEWER bars -- so a flat top yields exactly one pivot, the later of
// the equal bars; bars-ago indexing makes the SMALLER index the NEWER bar, so
// the strict half is the k < j loop. The confirmation lag is exactly strength
// bars, which is what makes the scan lookahead-safe; pivotLookback is EL's
// Length (candidate offsets 0..pivotLookback-1 inclusive) and the neighbourhood
// test reaches strength bars PAST the window, so the deepest index the scan
// touches is pivotLookback - 1 + swingStrength; a window with no pivot returns
// the -1 SENTINEL, guarded below; Occurrence 3+ is UNMEASURED and is never
// asked for; the comparisons carry the 2.22e-12 relational tolerance, hence
// el_gt / el_ge. No WFSafe_SwingHigh exists, so plain EL governs.
//
// MEASURED, EL_TLValue_Probe.txt (TLVALUE_FINDINGS.md section 4): TLValue is the
// pure two-point line Slope = (P2 - P1) / (B2 - B1);
// value = P1 + (target - B1) * Slope, anchored at the FIRST pair and
// extrapolating freely past both anchors. Bars-ago is used here, so the OLDER
// pivot (the LARGER bars-ago) is passed as P1/B1, the zero-drift spelling.
// Bar1 = Bar2 does NOT halt, it silently returns 0.0, so both twins guard
// B1 <> B2. The slope is hoisted out of the per-target arithmetic here where
// the twin recomputes it inside each TLValue call: identical doubles.
//
// THE THREE PARTS, in order:
//   1. THE BREAK. The close crosses the trend line, with the same slope gate
//      TrendLineBreak carries -- the newer pivot BEYOND the older one in the
//      trend direction -- so a line that does not slope with the trend cannot
//      arm the setup. ExtremeTestAfterTrendLineBreak's matureBars line-age gate
//      is NOT carried: it belongs to T13-04's statement of that rule and the
//      merged parameters for this setup name no such number.
//   2. THE FAILED TEST. Price comes back to within tolTicks of the trend
//      extreme AS IT STOOD AT THE BREAK, within testWindow bars of it.
//      barsSince >= 1 keeps the break bar itself from firing: on that bar the
//      extreme was just recorded and the test would be trivially true.
//   3. THE SIGNAL BAR. The test bar itself closes as a strong reversal bar in
//      the new direction -- a body of at least bodyFraction of its own range.
//      Only the BODY term is carried, because bodyFraction is the only signal
//      bar parameter the merge kept; a tail cap would be a number this setup's
//      sources do not give. The body test is a multiplication, never a ratio,
//      so a zero-range bar cannot raise EL's divide-by-zero.
//
// A LONG follows the break of a BEAR trend line (across the swing HIGHS) to the
// upside, and the extreme standing at the break is the bear move's lowest
// price, so the long side tests low[0] against the lowest low of the testWindow
// bars as of the break bar; the short side is the mirror at the high.
// THE TICK is EL's own MinMove / PriceScale, both VERIFIED and per-symbol
// constants for the whole run, written DIVISION-FIRST in both twins so the C++
// reads token for token against its EasyLanguage. Read once into a local.
//
// Scratch below is declared in localVariables, not at hook scope: the generator
// only prefixes declared locals, so a hook-scope declaration is a redefinition
// when this rule is placed twice in one strategy. Every one is fully assigned
// each bar before it is read.
pivS = (int)swingStrength;
pivW = (int)pivotLookback;
tickSz = ctx.MinMove() / ctx.PriceScale();
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2);
loSlope = 0.0;
hiSlope = 0.0;
if (haveLoLine) loSlope = (loP2 - loP1) / (loB2 - loB1);
if (haveHiLine) hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
loNow = 0.0;
hiNow = 0.0;
if (haveLoLine) loNow = loP1 + (0.0 - loB1) * loSlope;
if (haveHiLine) hiNow = hiP1 + (0.0 - hiB1) * hiSlope;
if (haveBrkUp) barsSinceUp = barsSinceUp + 1;
if (haveBrkDn) barsSinceDn = barsSinceDn + 1;
// The window extremes mirror EasyLanguage's Extremes(), which Highest() and
// Lowest() call: seeded at bar 0, scanning bars 1..Length-1, strict comparison,
// the window INCLUSIVE of the current bar.
loWin = low[0];
hiWin = high[0];
for (int i = 1; i < (int)testWindow; ++i) {
    if (el_lt(low[i], loWin)) loWin = low[i];
    if (el_gt(high[i], hiWin)) hiWin = high[i];
}
brokeUp = haveHiLine && el_lt(hiP2, hiP1) && el_gt(close[0], hiNow)
    && el_le(close[1], hiP1 + (1.0 - hiB1) * hiSlope);
brokeDn = haveLoLine && el_gt(loP2, loP1) && el_lt(close[0], loNow)
    && el_ge(close[1], loP1 + (1.0 - loB1) * loSlope);
if (brokeUp) {
    haveBrkUp = true;
    barsSinceUp = 0;
    extremeUp = loWin;
}
if (brokeDn) {
    haveBrkDn = true;
    barsSinceDn = 0;
    extremeDn = hiWin;
}
okUp = haveBrkUp && barsSinceUp >= 1 && el_le((double)barsSinceUp, testWindow)
    && el_le(std::fabs(low[0] - extremeUp), tolTicks * tickSz);
okDn = haveBrkDn && barsSinceDn >= 1 && el_le((double)barsSinceDn, testWindow)
    && el_le(std::fabs(high[0] - extremeDn), tolTicks * tickSz);
